import { useState } from 'react'
import { View, Text } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { Button, Grabber, ScreenTitle, Input, Switch } from '@/components'
import {
	KeyboardStickyView,
	KeyboardAwareScrollView
} from 'react-native-keyboard-controller'
import { router, useLocalSearchParams } from 'expo-router'
import { useAddSecretMutation, CreateEnvironment } from '@/generated/graphql'

const CONTINUE_BUTTON_OFFSET_OPEN = 24

export const AddSecretScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()

	const { projectGroupId } = useLocalSearchParams<{ projectGroupId?: string }>()

	const [name, setName] = useState('')
	const [secretValue, setSecretValue] = useState('')
	const [addToAllEnvironments, setAddToAllEnvironments] = useState(false)

	const [addSecret, { loading }] = useAddSecretMutation({
		refetchQueries: ['GetProjectGroupSecrets'],
		onCompleted: () => {
			router.back()
		},
		onError: (error) => {
			console.error('Failed to add secret:', error)
		}
	})

	const handleSaveSecret = () => {
		if (!projectGroupId) return

		addSecret({
			variables: {
				input: {
					projectGroupId,
					displayName: name.trim(),
					value: secretValue.trim(),
					environment: CreateEnvironment.DEVELOPMENT,
					addToAllEnvironments
				}
			}
		})
	}

	const isFormValid = name.trim() !== '' && secretValue.trim() !== ''

	return (
		<View style={styles.container(theme)}>
			<Grabber />
			<KeyboardAwareScrollView
				showsVerticalScrollIndicator={false}
				contentContainerStyle={styles.content}
				bottomOffset={120}
			>
				<ScreenTitle title="Add new secret" style={{ marginBottom: 20 }} />

				<View style={styles.form}>
					<Input
						label="Name"
						placeholder="API Key"
						value={name}
						onChangeText={setName}
						autoCapitalize="none"
						autoCorrect={false}
					/>

					<Input
						label="Secret value"
						placeholder="12345-ABCDE-67890-FGHIJ"
						value={secretValue}
						onChangeText={setSecretValue}
						autoCapitalize="none"
						autoCorrect={false}
					/>

					<View style={styles.switchContainer}>
						<Text style={styles.switchLabel(theme)}>
							Add to all environments
						</Text>
						<Switch
							value={addToAllEnvironments}
							onChange={setAddToAllEnvironments}
							trackColors={{
								on: colors[theme].gray[900],
								off: colors[theme].gray[50]
							}}
						/>
					</View>
				</View>
			</KeyboardAwareScrollView>

			<KeyboardStickyView
				offset={{
					closed: 0,
					opened: CONTINUE_BUTTON_OFFSET_OPEN
				}}
				style={styles.buttonContainer}
			>
				<View style={{ paddingBottom: insets.bottom + 16 }}>
					<Button
						text="Save secret"
						onPress={handleSaveSecret}
						disabled={!isFormValid || loading}
					/>
				</View>
			</KeyboardStickyView>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].gray[25],
		paddingHorizontal: 20
	}),
	content: {
		paddingBottom: 120
	},
	form: {
		gap: 20
	},
	switchContainer: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center'
	},
	switchLabel: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	buttonContainer: {
		paddingHorizontal: 20,
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0
	}
})
